/// In-memory implementation of [IOURepository].
///
/// Author: Lim Kai Zhe
/// Created: 25 Aug 2025
///
/// Stores [IOUEntry] objects in local memory for development and testing.
/// Not suitable for production use.
///
/// # Design Notes
/// - Uses a `Map<String, IOUEntry>` for efficient lookup by ID.
/// - Exposes both one-shot (`Future`) and real-time (`Stream`) access patterns.
/// - Seeds with demo data when in debug mode for faster prototyping.
/// - IDs are auto-generated by [IOUEntry] factory constructor.
library;

import 'dart:async';
import 'package:flutter/foundation.dart'; // for kDebugMode
import 'package:the_expense_tracker/features/iou/domain/domain.dart';

class InMemoryIOURepository implements IOURepository {
  final Map<String, IOUEntry> _storage = {};
  final StreamController<List<IOUEntry>> _controller =
      StreamController.broadcast();

  InMemoryIOURepository() {
    if (kDebugMode) {
      _seedDemoData();
    }
  }

  void _seedDemoData() {
    final alice = Participant.create("Alice");
    final bob = Participant.create("Bob");
    final charlie = Participant.create("Charlie");

    final demoEntries = [
      IOUEntry(
        description: "Lunch at cafe",
        amount: MoneyValue.fromDouble(30.00, "MYR"),
        date: DateTime.now().subtract(const Duration(days: 1)),
        payer: alice,
        shares: [
          ParticipantShare(alice, MoneyValue.fromDouble(10.00, "MYR")),
          ParticipantShare(bob, MoneyValue.fromDouble(10.00, "MYR")),
          ParticipantShare(charlie, MoneyValue.fromDouble(10.00, "MYR")),
        ],
      ),
      IOUEntry(
        description: "Movie tickets",
        amount: MoneyValue.fromDouble(45.00, "MYR"),
        date: DateTime.now().subtract(const Duration(days: 2)),
        payer: bob,
        shares: [
          ParticipantShare(alice, MoneyValue.fromDouble(15.00, "MYR")),
          ParticipantShare(bob, MoneyValue.fromDouble(15.00, "MYR")),
          ParticipantShare(charlie, MoneyValue.fromDouble(15.00, "MYR")),
        ],
      ),
      IOUEntry(
        description: "Taxi ride",
        amount: MoneyValue.fromDouble(18.00, "MYR"),
        date: DateTime.now(),
        payer: charlie,
        shares: [
          ParticipantShare(alice, MoneyValue.fromDouble(10.00, "MYR")),
          ParticipantShare(charlie, MoneyValue.fromDouble(8.00, "MYR")),
        ],
      ),
    ];

    for (final entry in demoEntries) {
      _storage[entry.id] = entry;
    }
    _notifyListeners();
  }

  void _notifyListeners() {
    _controller.add(_storage.values.toList(growable: false));
  }

  @override
  Future<List<IOUEntry>> getAll() async {
    return _storage.values.toList(growable: false);
  }

  @override
  Stream<List<IOUEntry>> watchAll() => _controller.stream;

  @override
  Future<void> add(IOUEntry entry) async {
    _storage[entry.id] = entry;
    _notifyListeners();
  }

  @override
  Future<IOUEntry?> getById(String id) async {
    return _storage[id];
  }

  @override
  Future<void> remove(String id) async {
    _storage.remove(id);
    _notifyListeners();
  }

  @override
  Future<void> update(IOUEntry entry) async {
    if (!_storage.containsKey(entry.id)) {
      throw ArgumentError("Entry with id=${entry.id} does not exist");
    }
    _storage[entry.id] = entry;
    _notifyListeners();
  }

  /// Closes the repository's stream controller.
  Future<void> dispose() async {
    await _controller.close();
  }
}
